function showPage(name) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  // home is not a .page div, it's #page-home
  const pg = document.getElementById('page-' + name);
  if (pg) pg.classList.add('active');
  else document.getElementById('page-home').classList.add('active');
  window.scrollTo({top: 0, behavior: 'smooth'});
  if (name === 'blog') renderBlogIndex();
  if (name === 'checklist') buildChecklist();
}

function openArticle(slug) {
  const art = ALL_ARTICLES.find(a => a.slug === slug);
  if (!art) return;
  document.getElementById('artTag').textContent = art.tag;
  document.getElementById('artDate').textContent = '📅 ' + art.date;
  document.getElementById('artTime').textContent = '⏱ ' + art.time;
  document.getElementById('artTitle').textContent = art.title;
  document.getElementById('artBreadcrumb').textContent = art.title;
  document.getElementById('artIntro').textContent = art.intro;
  document.getElementById('artBody').innerHTML = art.body;

  // Related articles
  const related = (art.related || ['best-hosting-wordpress','shared-vs-vps-hosting','cheap-hosting-india'])
    .map(s => ALL_ARTICLES.find(a => a.slug === s)).filter(Boolean).slice(0,3);
  document.getElementById('relGrid').innerHTML = related.map(r =>
    `<div class="rel-card" onclick="openArticle('${r.slug}')">
      <h4>${r.title}</h4>
      <p>${r.tag} · ${r.time}</p>
    </div>`
  ).join('');

  showPage('article');
}

