function getProviderCards(traffic, wtype, loc) {
  const tierKey = traffic === 'under10k' ? 'shared'
    : traffic === '10k-100k' ? 'vps'
    : traffic === '100k-500k' ? 'cloud'
    : 'dedicated';

  // Smart ordering by use case
  const orders = {
    blog:      ['hostinger','bluehost','siteground','godaddy','bigrock','milesweb','hostgator','cloudways','aws','digitalocean','googlecloud','kinsta'],
    business:  ['hostinger','bluehost','godaddy','siteground','bigrock','hostgator','milesweb','cloudways','aws','digitalocean','googlecloud','kinsta'],
    ecommerce: ['hostinger','bluehost','cloudways','siteground','godaddy','kinsta','aws','digitalocean','bigrock','milesweb','googlecloud','hostgator'],
    webapp:    ['digitalocean','aws','googlecloud','cloudways','hostinger','kinsta','siteground','bluehost','godaddy','bigrock','milesweb','hostgator'],
  };
  // For large traffic prioritise cloud/enterprise
  let order = orders[wtype] || orders.business;
  if (traffic === 'over500k') order = ['aws','googlecloud','digitalocean','kinsta','cloudways','siteground','hostinger','bluehost','godaddy','bigrock','milesweb','hostgator'];
  if (traffic === '100k-500k') order = ['aws','digitalocean','cloudways','googlecloud','kinsta','siteground','hostinger','bluehost','godaddy','bigrock','milesweb','hostgator'];

  const topPick = order[0];
  // Show top 6 in result to keep it clean
  return order.slice(0, 6).map((key) => {
    const p = PROVIDERS[key];
    const price = p[tierKey] || p.shared;
    const why = p.why[tierKey] || p.why.shared;
    const isTop = key === topPick;
    return `<div class="res-prov-card${isTop?' top-pick':''}">
      <div class="res-prov-top">
        <span class="res-prov-name">${p.name}</span>
        ${isTop ? '<span class="res-prov-badge">⭐ TOP PICK</span>' : ''}
      </div>
      <div class="res-prov-price">${price}</div>
      <div class="res-prov-why">${why}</div>
      <a href="${p.url}" target="_blank" rel="noopener sponsored" class="res-prov-btn">Visit ${p.name.replace(/^.\s/,'')} →</a>
    </div>`;
  }).join('');
}

function calculate() {
  const wtype = document.querySelector('input[name="wtype"]:checked');
  const cms   = document.querySelector('input[name="cms"]:checked');
  const traffic = document.getElementById('traffic').value;
  const loc   = document.querySelector('input[name="loc"]:checked');
  const size  = parseInt(document.getElementById('sizeSlider').value);

  if (!wtype || !cms || !traffic || !loc) {
    alert('Please complete all 5 fields before calculating.'); return;
  }

  const t = wtype.value, c = cms.value, l = loc.value;

  // Base recommendation by traffic
  const tiers = {
    'under10k':  {type:'Shared Hosting',  ram:'1–2 GB RAM', storage: size<=5?'10 GB SSD':'20 GB SSD', min:69,   max:299},
    '10k-100k':  {type:'VPS Hosting',     ram:'2–4 GB RAM', storage: size<=20?'40 GB SSD':'80 GB SSD', min:500,  max:1500},
    '100k-500k': {type:'Cloud Hosting',   ram:'8–16 GB RAM', storage: size<=50?'100 GB SSD':'200 GB SSD', min:2000, max:6000},
    'over500k':  {type:'Dedicated Server',ram:'32–64 GB RAM', storage:'500 GB+ SSD', min:8000, max:25000},
  };
  const tier = tiers[traffic];
  let min = tier.min, max = tier.max;
  const notes = [];

  if (t === 'ecommerce') { min+=Math.round(min*.3); max+=Math.round(max*.3); notes.push('+30% for Ecommerce (SSL, payments)'); }
  if (c === 'wordpress')  { min+=Math.round(min*.15); max+=Math.round(max*.15); notes.push('+15% for WordPress (caching, plugins)'); }
  if (c === 'joomla')     { min+=Math.round(min*.10); max+=Math.round(max*.10); notes.push('+10% for Joomla (extensions, PHP overhead)'); }
  if (size > 50) { min+=200; max+=800; notes.push('Extra cost for 50+ GB storage'); }

  const locs = {
    india:  '🇮🇳 Mumbai, India — Hostinger IN · AWS ap-south-1 · DigitalOcean BLR',
    usa:    '🇺🇸 US East (Virginia) — AWS us-east-1 · DigitalOcean NYC · Bluehost US',
    europe: '🇪🇺 Frankfurt / Amsterdam — AWS eu-central-1 · Hostinger EU · DigitalOcean AMS',
    global: '🌍 Global CDN — Cloudflare + Singapore or Frankfurt origin server',
  };

  document.getElementById('rTitle').textContent = tier.type;
  document.getElementById('rCost').textContent = `₹${min.toLocaleString()} – ₹${max.toLocaleString()}/month`;
  document.getElementById('rSpecs').innerHTML = [
    ['Hosting Type', tier.type], ['Recommended RAM', tier.ram],
    ['Storage', tier.storage], ['Website Type', cap(t)],
    ['Platform / CMS', cap(c)], ['Website Size', size+' GB'],
  ].map(([l,v]) => `<div class="spec-card"><div class="spec-lbl">${l}</div><div class="spec-val">${v}</div></div>`).join('')
  + (notes.length ? `<div class="spec-card" style="grid-column:1/-1"><div class="spec-lbl">Cost Adjustments</div><div class="spec-val" style="font-weight:400;font-size:.85rem;color:var(--text2)">${notes.join(' · ')}</div></div>` : '');
  document.getElementById('rLoc').innerHTML = `<strong>📍 Recommended Server Location:</strong> ${locs[l]}`;

  // Affiliate provider cards — smart-matched to inputs
  document.getElementById('rProviders').innerHTML = getProviderCards(traffic, t, l);

  const res = document.getElementById('calcResult');
  res.style.display = 'block';
  res.scrollIntoView({behavior:'smooth', block:'start'});
}

function cap(s) {
  const m = {wordpress:'WordPress',joomla:'Joomla',custom:'Custom Code',other:'Other',blog:'Blog',business:'Business',ecommerce:'Ecommerce',webapp:'Web Application'};
  return m[s] || s;
}

function resetCalc() {
  document.getElementById('calcResult').style.display = 'none';
  document.querySelectorAll('input[type=radio]').forEach(r => r.checked = false);
  document.querySelectorAll('.opt').forEach(o => o.classList.remove('sel'));
  document.getElementById('traffic').value = '';
  document.getElementById('sizeSlider').value = 5;
  document.getElementById('sizeVal').textContent = '5';
  document.getElementById('calcForm').scrollIntoView({behavior:'smooth'});
}

