// ============================================
// CHECKLIST ENGINE
// ============================================
let clState = {};

function buildChecklist() {
  const saved = localStorage.getItem('hc_checklist');
  if (saved) try { clState = JSON.parse(saved); } catch(e){}

  let total = 0;
  document.getElementById('checklistGrid').innerHTML = CHECKLIST_DATA.map(group => {
    const items = group.items.map((item, i) => {
      const key = group.group + '_' + i;
      const done = clState[key] || false;
      total++;
      return `<div class="cl-item${done?' done-item':''}" onclick="toggleCheck('${key}',this)">
        <div class="cl-box${done?' done':''}">✓</div>
        <span class="cl-label">${item}</span>
      </div>`;
    }).join('');
    return `<div class="cl-group"><h3>${group.group}</h3><div class="cl-items">${items}</div></div>`;
  }).join('');
  updateClProgress();
}

function toggleCheck(key, el) {
  clState[key] = !clState[key];
  localStorage.setItem('hc_checklist', JSON.stringify(clState));
  const box = el.querySelector('.cl-box');
  box.classList.toggle('done', clState[key]);
  el.classList.toggle('done-item', clState[key]);
  updateClProgress();
}

function updateClProgress() {
  const total = Object.values(CHECKLIST_DATA).reduce((s,g) => s + g.items.length, 0);
  const done = Object.values(clState).filter(Boolean).length;
  const pct = Math.round((done/total)*100);
  document.getElementById('clProgressText').textContent = `${done} of ${total} tasks completed`;
  document.getElementById('clFill').style.width = pct + '%';
  document.getElementById('clPct').textContent = pct + '%';
}

function resetChecklist() {
  if (!confirm('Reset all checklist progress?')) return;
  clState = {};
  localStorage.removeItem('hc_checklist');
  buildChecklist();
}

function printChecklist() {
  const win = window.open('', '_blank');
  const groups = CHECKLIST_DATA.map(g =>
    `<div style="margin-bottom:24px;break-inside:avoid">
      <h3 style="font-size:14px;font-weight:700;margin-bottom:10px;padding-bottom:6px;border-bottom:1px solid #ddd">${g.group}</h3>
      ${g.items.map(item => `<div style="display:flex;gap:10px;align-items:flex-start;margin-bottom:7px;font-size:13px">
        <div style="width:16px;height:16px;border:1.5px solid #999;border-radius:3px;flex-shrink:0;margin-top:1px"></div>
        <span>${item}</span>
      </div>`).join('')}
    </div>`
  ).join('');
  win.document.write(`<!DOCTYPE html><html><head><title>Hosting Setup Checklist — HostCalculator.com</title>
  <style>body{font-family:sans-serif;max-width:800px;margin:0 auto;padding:30px;color:#111}
  h1{font-size:22px;margin-bottom:4px}p{color:#666;font-size:13px;margin-bottom:24px}
  .grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}
  @media print{@page{margin:1cm}}</style></head>
  <body><h1>✅ Hosting Setup Checklist</h1>
  <p>HostCalculator.com — Complete this checklist when setting up your website hosting.</p>
  <div class="grid">${groups}</div>
  <p style="margin-top:30px;font-size:11px;color:#999">Generated by HostCalculator.com · hostcalculator.com</p>
  <script>window.onload=()=>window.print()<\/script></body></html>`);
  win.document.close();
}

